mapper.select:
select t1.* from (SELECT t.*, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_TYPE' AND sc.code_value = t.fill_type) FILL_TYPE_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_YEAR' AND sc.code_value = t.fill_year) FILL_YEAR_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_QUARTER' AND sc.code_value = t.fill_quarter) FILL_QUARTER_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_MON' AND sc.code_value = t.fill_mon) FILL_MON_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_WEEK' AND sc.code_value = t.fill_week) FILL_WEEK_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_STATUS' AND sc.code_value = t.plan_status) PLAN_STATUS_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_STATUS' AND sc.code_value = t.req_status) req_status_n, (select s.description from sys_user s where s.user_id = t.fill_user_id)FILL_USER_ID_N, (select u.unit_name from fnd_org_unit u where u.unit_id = t.unit_id )unit_id_n FROM jc_fund_filling t )t1 where 1 = 1 and t1.req_status is not null
and t1.filling_id = #{fillingId}
and t1.fill_type = #{fillType}
and t1.fill_year = #{fillYear}
and t1.fill_quarter = #{fillQuarter}
and t1.fill_week = #{fillWeek}
and t1.fill_mon = #{fillMon}
and (t1.unit_id = #{unitId} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}) )
and t1.fill_user_id_n = #{fillUserIdN}
and t1.req_status = #{reqStatus}

SELECT  t.*
FROM jc_fund_filling t
where 1 = 1
and t.plan_status = 'APPROVED'
and t.document_type = 'FILL'
and t.fill_type = 'WEEK'
and t.fill_year = #{fillYear}
and t.fill_mon = #{fillMon}
and t.fill_week = #{fillWeek}
and t.unit_id = #{unitId}

SELECT  t.*
FROM jc_fund_filling t
where 1 = 1
and t.plan_status = 'APPROVED'
and t.document_type = 'SUMMARY'
and t.fill_type = 'WEEK'
and t.fill_year = #{fillYear}
and t.fill_mon = #{fillMon}
and t.fill_week = #{fillWeek}

select t1.* from (SELECT t.*, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_TYPE' AND sc.code_value = t.fill_type) FILL_TYPE_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_YEAR' AND sc.code_value = t.fill_year) FILL_YEAR_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_QUARTER' AND sc.code_value = t.fill_quarter) FILL_QUARTER_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_MON' AND sc.code_value = t.fill_mon) FILL_MON_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_WEEK' AND sc.code_value = t.fill_week) FILL_WEEK_N, (SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'FP.FILL_STATUS' AND sc.code_value = t.plan_status) PLAN_STATUS_N, (select s.description from sys_user s where s.user_id = t.fill_user_id)FILL_USER_ID_N, (select u.unit_name from fnd_org_unit u where u.unit_id = t.unit_id )unit_id_n FROM jc_fund_filling t )t1 where 1 = 1 and t1.document_type = 'FILL'
and t1.filling_id = #{fillingId}
and t1.fill_type = #{fillType}
and t1.fill_year = #{fillYear}
and t1.fill_quarter = #{fillQuarter}
and t1.fill_week = #{fillWeek}
and t1.fill_mon = #{fillMon}
and (t1.unit_id = #{unitId} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}) )
and t1.fill_user_id_n = #{fillUserIdN}
and t1.plan_status = #{planStatus}
order by t1.creation_date desc

